diff --git a/src/preview.cpp b/src/preview.cpp
index e8d199b..b009ca9 100644
--- a/src/preview.cpp
+++ b/src/preview.cpp
@@ -831,15 +831,17 @@ bool ai7ThumbnailSize(size_t width, size_t height, size_t& rgbSize) {
     return false;

   constexpr size_t bytesPerPixel = 3;
+  // The decoded RGB rows are padded to a 4-byte boundary.
+  constexpr size_t rowAlignment = 4;

-  if (width > std::numeric_limits<size_t>::max() / height)
+  if (width > (std::numeric_limits<size_t>::max() - (rowAlignment - 1)) / bytesPerPixel)
     return false;

-  const size_t pixels = width * height;
-  if (pixels > std::numeric_limits<size_t>::max() / bytesPerPixel)
+  const size_t rowSize = (width * bytesPerPixel + rowAlignment - 1) / rowAlignment * rowAlignment;
+  if (rowSize > std::numeric_limits<size_t>::max() / height)
     return false;

-  rgbSize = pixels * bytesPerPixel;
+  rgbSize = rowSize * height;
   return rgbSize <= maxAi7ThumbnailSize;
 }

